def count_deaf_rats(pied_piper_string):
    parts = pied_piper_string.split(' P')
    if len(parts) == 1:
        return 0
    left_part, right_part = parts[0], parts[1]

    deaf_left = 0
    for i in range(0, len(left_part), 2):
        if i + 1 < len(left_part) and left_part[i:i+2] == '~O':
            deaf_left += 1

    deaf_right = 0
    for i in range(0, len(right_part), 2):
        if i + 1 < len(right_part) and right_part[i:i+2] == 'O~':
            deaf_right += 1

    return deaf_left + deaf_right
